window.QURAN_TAFSIR = {"sources":[{"key":"muyassar","name":"التفسير الميسر","lang":"ar"},{"key":"saadi","name":"تفسير السعدي","lang":"ar"},{"key":"kathir","name":"Ibn Kathir (Abridged)","lang":"en"}],"verses":{"1":{"muyassar":"ألم تعلم -أيها الرسول- كيف فعل ربك بأصحاب الفيل: أبرهة الحبشي وجيشه الذين أرادوا تدمير الكعبة المباركة؟","kathir":"","saadi":"أي: أما رأيت من قدرة الله وعظيم شأنه، ورحمته بعباده، وأدلة توحيده، وصدق رسوله محمد صلى الله عليه وسلم، ما فعله الله بأصحاب الفيل، الذين كادوا بيته الحرام وأرادوا إخرابه، فتجهزوا لأجل ذلك، واستصحبوا معهم الفيلة لهدمه، وجاءوا بجمع لا قبل للعرب به، من الحبشة واليمن، فلما انتهوا إلى قرب مكة، ولم يكن بالعرب مدافعة، وخرج أهل مكة من مكة خوفًا على أنفسهم منهم."},"2":{"muyassar":"ألم يجعل ما دبَّروه من شر في إبطال وتضييع؟","kathir":"","saadi":"كفى الله شرهم، ورد كيدهم في نحورهم"},"3":{"muyassar":"وبعث عليهم طيرًا في جماعات متتابعة، تقذفهم بحجارة من طين متحجِّر.","kathir":"","saadi":"أرسل الله عليهم طيرًا أبابيل أي: متفرقة."},"5":{"muyassar":"فجعلهم به محطمين كأوراق الزرع اليابسة التي أكلتها البهائم ثم رمت بها.","kathir":"","saadi":"وصاروا كعصف مأكول، وكفى الله شرهم، ورد كيدهم في نحورهم، [وقصتهم معروفة مشهورة] وكانت تلك السنة التي ولد فيها رسول الله صلى الله عليه وسلم، فصارت من جملة إرهاصات دعوته، ومقدمات رسالته، فلله الحمد والشكر."},"4":{"kathir":"","saadi":"تحمل حجارة محماة من سجيل، فرمتهم بها، وتتبعت قاصيهم ودانيهم، فخمدوا وهمدوا."}}};
